content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-16-travel-ticket-007

=== 用户原始指令 (query.txt) ===
给我整张火车票卡,显示开车倒计时,点能看检票口,快发车提醒我下

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我整张火车票卡,显示开车倒计时,点能看检票口,快发车提醒我下",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "train-ticket-g1234-20260709"
        }
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "ticket": {
        "entityId": {
          "type": "string",
          "description": "火车票对应的日历行程唯一标识，用于打开行程详情查看检票口等信息。",
          "sampleValue": "train-ticket-g1234-20260709"
        },
        "trainNo": {
          "type": "string",
          "description": "车次号，用于识别当前火车票。",
          "sampleValue": "G1234"
        },
        "statusText": {
          "type": "string",
          "description": "当前行程提醒状态。",
          "sampleValue": "快发车"
        },
        "countdownText": {
          "type": "string",
          "description": "距离开车的倒计时展示文本。",
          "sampleValue": "12分钟"
        },
        "departureTimeText": {
          "type": "string",
          "description": "开车时间展示文本。",
          "sampleValue": "14:32 开"
        },
        "routeText": {
          "type": "string",
          "description": "本次火车票的出发站与到达站摘要。",
          "sampleValue": "北京南-上海虹桥"
        },
        "gateActionLabel": {
          "type": "string",
          "description": "查看检票口的短入口文案。",
          "sampleValue": "检票口"
        },
        "reminderStatus": {
          "type": "string",
          "description": "发车提醒是否已设置的短状态。",
          "sampleValue": "已提醒"
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/tram_fill.svg",
      "description": "有轨电车实心图标，黑色，适合用于铁路或公共交通票务行程的识别图标。"
    }
  ]
}

